// Функция для форматирования одного объекта
function formatObject(obj) {
  let result = '';

  // Проходим по всем полям объекта
  for (const [key, value] of Object.entries(obj)) {
    // Пропускаем поля со значением null или undefined
    if (value !== null && value !== undefined) {
      // Добавляем пару "ключ: значение" с переносом строки
      result += `${key}: ${value}\n\n`;
    }
  }

  return result;
}

// Обрабатываем все входящие элементы
const outputItems = inputData.map((item, index) => {
  const jsonData = item.json;

  let formattedText = '';

  // Если данные представляют собой массив объектов
  if (Array.isArray(jsonData)) {
    jsonData.forEach((obj, objIndex) => {
      if (objIndex > 0) {
        formattedText += '\n--- Объект ' + (objIndex + 1) + ' ---\n\n';
      }
      formattedText += formatObject(obj);
    });
  } 
  // Если данные представляют собой один объект
  else if (typeof jsonData === 'object') {
    formattedText = formatObject(jsonData);
  }

  return {
    json: {
      formatted_text: formattedText.trim() // Убираем лишние переносы в конце
    }
  };
});

return outputItems;

